for i in range(1,9):
    p=H%i; d=json.load(open(p))
    assert len(d['signature'])==len(S[i]),(i,len(d['signature']),len(S[i]))
    d['tagline']=T[i]
    for x,(n,w) in zip(d['signature'],S[i]):
        x['name']=n; x['why']=w
        assert len(n)<=50 and len(w)<=160,(i,n,len(w))
    assert len(T[i])<=80 and T[i]!=d['name'],i
    json.dump(d,open(p,'w'),indent=1,ensure_ascii=False)
    print(i,len(T[i]),'ok')
